DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:HOA 045", "old_status": "partial_multi_question", "status": "ready", "question_id": "0197317a-b55e-54f3-af92-c0a2ab049131", "stem": "What is the solution set of \\(\\frac23x+y=-3\\) and \\(\\frac13x+\\frac12y=-3\\)?", "choices": [{"key": "A", "text": "{(−6,1)}"}, {"key": "B", "text": "{(6,9)}"}, {"key": "C", "text": "{(6,−7)}"}, {"key": "D", "text": "No solution"}], "type": "mcq", "correct": "D", "explanation": "Doubling the second equation gives (2/3)x+y=−6. The first requires that identical left-hand side to equal −3. Both cannot hold, so the system has no solution.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Visually confirmed the clipped top numerator 2 on page 32 and separated original Q4 from Q5.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 32, "extra_sources": [], "parts": [{"label": "Q5", "question_id": "fcf283df-5aa5-54c1-a977-56e541c02e0b", "stem": "Two distinct lines represent a system of linear equations with no solution. How are the lines related?", "choices": [{"key": "A", "text": "They intersect at one point."}, {"key": "B", "text": "They have the same x-intercept."}, {"key": "C", "text": "They are parallel."}, {"key": "D", "text": "They coincide."}], "type": "mcq", "correct": "C", "explanation": "A solution corresponds to an intersection. Distinct lines in a plane that never intersect are parallel. Coincident lines would instead give infinitely many solutions.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 066", "old_status": "partial_multi_question", "status": "ready", "question_id": "75b88990-5be9-5077-9f93-c37a8abf1c6d", "stem": "A line passes through (2a,a²) and (2b,b²), where a≠b. Which expression gives its slope?", "choices": [{"key": "A", "text": "\\(a/b\\)"}, {"key": "B", "text": "\\((a+b)/2\\)"}, {"key": "C", "text": "\\(2/(a+b)\\)"}, {"key": "D", "text": "\\((a^2-b^2)/(a-b)\\)"}], "type": "mcq", "correct": "B", "explanation": "The slope is (b²−a²)/(2b−2a)=[(b−a)(b+a)]/[2(b−a)]=(a+b)/2, using a≠b. This is the general formula in B.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Extracted complete original Q17. The preceding perpendicular-line question has no graph of k and remains excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 44, "extra_sources": []}, {"id": "clean:HOA 067", "old_status": "partial_multi_question", "status": "ready", "question_id": "63c33e95-ca4a-5765-bb87-daeb39c9faed", "stem": "The system \\(x+3y=b/2\\), \\(4x+4ay=20\\) has exactly one solution. Which pair of values is possible?", "choices": [{"key": "A", "text": "a=3, b=10"}, {"key": "B", "text": "a=3, b=12"}, {"key": "C", "text": "a=3, b=−4"}, {"key": "D", "text": "a=10, b=3"}], "type": "mcq", "correct": "D", "explanation": "Multiply the first equation by 4 to get 4x+12y=2b. A unique intersection with 4x+4ay=20 requires 4a≠12, or a≠3. Only D has a≠3; b changes the intercept but not this uniqueness condition.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Extracted complete Q19. The preceding numbered-region question lacks its graph; its inequalities alone cannot determine a region label, so that fragment remains excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 45, "extra_sources": []}, {"id": "clean:HOA 069", "old_status": "partial_multi_question", "status": "ready", "question_id": "e66205b1-78e3-5b41-9c3e-371ac6d29b70", "stem": "The table shows employees by age and sports participation. If an employee under 40 is chosen at random, what is the probability that the employee participates in sports?", "choices": [{"key": "A", "text": "2/13"}, {"key": "B", "text": "11/27"}, {"key": "C", "text": "11/16"}, {"key": "D", "text": "11/13"}], "type": "mcq", "correct": "D", "explanation": "Conditioning on age under 40 restricts the sample to 260 employees. Of those, 220 participate in sports. The conditional probability is 220/260=11/13.", "topic": "Statistics, Probability & Data Analysis", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 47, "extra_sources": [], "assets": {"html": "<table><tr><th>Age</th><th>Sports</th><th>No sports</th><th>Total</th></tr><tr><th>Under 40</th><td>220</td><td>40</td><td>260</td></tr><tr><th>40 and older</th><td>100</td><td>180</td><td>280</td></tr><tr><th>Total</th><td>320</td><td>220</td><td>540</td></tr></table>"}, "parts": [{"label": "Q26", "question_id": "ef9c1700-185b-514e-8cf1-3f69920449eb", "stem": "Ryan estimates x concert attendees, while the actual number is y. Which inequality expresses that his estimate is within 50 of the actual count?", "choices": [{"key": "A", "text": "|x−y|≤50"}, {"key": "B", "text": "x≤y+50"}, {"key": "C", "text": "x≥y−50"}, {"key": "D", "text": "x+y≤50"}], "type": "mcq", "correct": "A", "explanation": "The error’s magnitude is |x−y|. Being within 50 means this distance is at most 50, giving |x−y|≤50. Each one-sided bound alone permits an arbitrarily large error in the other direction.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified."}]}, {"id": "clean:HOA 078", "old_status": "partial_multi_question", "status": "ready", "question_id": "da399eb6-42ef-5e12-9611-9822489d46d1", "stem": "Which system has infinitely many solutions?", "choices": [{"key": "A", "text": "\\(2x-3y=1,\\quad x+3y=4\\)"}, {"key": "B", "text": "\\(-2x+y=-1,\\quad5y=-2x\\)"}, {"key": "C", "text": "\\(3x+y=2,\\quad x=-5y\\)"}, {"key": "D", "text": "\\(-2x-2y=4,\\quad y=-x-2\\)"}], "type": "mcq", "correct": "D", "explanation": "In D, dividing the first equation by −2 gives x+y=−2, or y=−x−2, exactly the second equation. Both describe the same line. In A, B, and C, the paired lines have different slopes, so they have one solution each.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Isolated Q19; the preceding collinearity fragment lacks the other points and remains excluded.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 51, "extra_sources": []}, {"id": "clean:PSD 025", "old_status": "needs_source_reconstruction", "status": "ready", "question_id": "c4387f13-14de-5af1-be69-defc2f90e94a", "stem": "The histogram summarizes ages for about 11,200 cases. Which listed age is the most plausible median?", "choices": [{"key": "A", "text": "23"}, {"key": "B", "text": "31"}, {"key": "C", "text": "56"}, {"key": "D", "text": "68"}], "type": "mcq", "correct": "B", "explanation": "The median is near the 5,600th case when ages are ordered. The first three age bins (under 30) contain about 4,300 cases. Including the 30–40 bin raises the cumulative count to about 6,700, so the median lies in 30–40. Among the choices, only 31 lies in that interval.", "topic": "Statistics, Probability & Data Analysis", "note": "Original age-axis labels and bar lengths checked at enlarged resolution. Split Q15 and Q16 and retained the full shared histogram; counts are approximate readings of the chart.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 164, "extra_sources": [], "assets": {"figure": "data:image/jpeg;base64,"}, "parts": [{"label": "Q16", "question_id": "2ab2712a-3d29-54e5-ace7-8911594c715f", "stem": "Using the histogram, which fraction is closest to the number of cases below age 10 divided by the number above age 80?", "choices": [{"key": "A", "text": "10/80"}, {"key": "B", "text": "215/410"}, {"key": "C", "text": "410/215"}, {"key": "D", "text": "80/10"}], "type": "mcq", "correct": "C", "explanation": "The under-10 bar is about 400 cases and the over-80 bar about 200, so the requested ratio is about 2. Of the choices, 410/215≈1.907 is closest. The reversed fraction uses the wrong order; 10/80 and 80/10 compare age cutoffs instead of case counts.", "topic": "Statistics, Probability & Data Analysis", "note": "Split from the original shared crop; original PDF visually checked and solution independently verified.", "assets": {"figure": "data:image/jpeg;base64,"}}]}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
